package app.xiaohe.tests;
import android.app.*;import android.content.Context;import android.os.Bundle;import app.xiaohe.assistant.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;

public final class DataSmoke extends Instrumentation {
  private String mode="";
  public void onCreate(Bundle arguments){super.onCreate(arguments);mode=arguments==null?"":arguments.getString("mode","");start();}
  private void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
  private byte[] backup(Store store)throws Exception {ByteArrayOutputStream out=new ByteArrayOutputStream();new Backup(getTargetContext()).exportTo(out);return out.toByteArray();}
  private byte[] altered(byte[] input,boolean path,boolean corrupt)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(input));ZipOutputStream out=new ZipOutputStream(bytes)){ZipEntry e;while((e=in.getNextEntry())!=null){out.putNextEntry(new ZipEntry(e.getName()));if(corrupt&&e.getName().startsWith("attachments/"))out.write("changed".getBytes("UTF-8"));else{byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}out.closeEntry();}if(path){out.putNextEntry(new ZipEntry("../outside.txt"));out.write(1);out.closeEntry();}}return bytes.toByteArray();}
  public void onStart(){Bundle results=new Bundle();try{
    if(mode.equals("schedule-query")){ScheduleSmoke.run(getTargetContext());results.putString("status","passed");results.putString("verified","calendar ranges and full SQLite schedules; immutable query anchors; cancellations, reschedules, DST and cache-independent recall");finish(Activity.RESULT_OK,results);return;}
    if(mode.equals("absolute-dates")){AbsoluteDateSmoke.run(getTargetContext());results.putString("status","passed");results.putString("verified","first-save absolute dates before AI; offline pending and delayed voice; raw source/history preserved; retry/import freeze; source guards and absolute date FTS");finish(Activity.RESULT_OK,results);return;}
    if(mode.equals("organizer")){OrganizerSmoke.run(getTargetContext());results.putString("status","passed");results.putString("verified","manual organize backfills legacy relative dates from original source; reports converted/remaining/archived counts; preserves originals and remains idempotent");finish(Activity.RESULT_OK,results);return;}
    if(mode.equals("organizer-ui")){OrganizerUiSmoke.run(this);results.putString("status","passed");results.putString("verified","actual native organize-button click; immediate progress, visible completion and optional time clues");finish(Activity.RESULT_OK,results);return;}
    if(mode.equals("schedule-api")){ScheduleApiSmoke.run(getTargetContext());results.putString("status","passed");results.putString("verified","offline local schedules and recorded voice; immutable readable query dates and time-zone context; actual fixture API calendar evidence");finish(Activity.RESULT_OK,results);return;}
    if(mode.equals("clipboard")){ClipboardSmoke.run(this);results.putString("status","passed");results.putString("verified","trusted native paste button with Android IME composing text; retained password content after focus changes; masked key; no desktop helper");finish(Activity.RESULT_OK,results);return;}
    Context c=getTargetContext();Store db=Store.get(c);if(mode.equals("feel-seed")){FeelUpgradeSmoke.seed(db,c);results.putString("status","seeded_1.1");finish(Activity.RESULT_OK,results);return;}if(mode.equals("feel-upgrade")){FeelUpgradeSmoke.verify(db,c);results.putString("status","passed");results.putString("verified","1.1-to-1.2 manual text/source/history/key retention; quiet unscheduled migration; completed flexible archive");finish(Activity.RESULT_OK,results);return;}if(mode.equals("assistant-feel")){AssistantFeelSmoke.run(db,c);results.putString("status","passed");results.putString("verified","quiet unscheduled plans; contextual homonyms; assumed date provenance; optional uncertainty; necessary reminder questions; single-target continuation; durable deferral; no implicit rescheduling");finish(Activity.RESULT_OK,results);return;}if(mode.equals("experience-ai")){ExperienceAiSmoke.run(db,c);results.putString("status","passed");results.putString("verified","actual text-only AI fixture; casual unscheduled input; contextual preference change; no date homework; reminder dialogue continuation; deferral and schedule claim checks");finish(Activity.RESULT_OK,results);return;}if(mode.equals("ai-backup")){AiBackupChecks.run(db,c);results.putString("status","passed");results.putString("verified","v1/v2 streaming backup protocol; orphan snapshots; immutable history/reordered keys; missing references rejected; relevant same-name entities only; material search windows; full Office node with partial coverage");finish(Activity.RESULT_OK,results);return;}if(mode.equals("large")){LargeRowSmoke.run(db,c);results.putString("status","passed");results.putString("verified","JSON rows above 2MB for files/messages/memories/versions; full Unicode/emoji chunk reads; indexed lookup; material metadata projection; streaming large backup re-import and missing-record restore; unchanged original SHA");finish(Activity.RESULT_OK,results);return;}if(mode.equals("final")){FinalSmoke.run(db,c);results.putString("status","passed");results.putString("verified","deep task pagination; original relative wording after date confirmation; appended versions; disputed reminder blocked; current facts searchable");finish(Activity.RESULT_OK,results);return;}if(mode.equals("seed")){String sfid="upgrade-media-0001";File original=db.filePath(sfid);try(InputStream in=getContext().getAssets().open("reference.png");OutputStream out=new FileOutputStream(original)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}db.put("files",new JSONObject().put("id",sfid).put("created",System.currentTimeMillis()).put("name","旧版原始截图.png").put("mime","image/png").put("size",original.length()).put("sha256",MediaProcessor.hash(original)));JSONObject m=db.message("user","昨天和小林吃饭；这是 1.0 的原话，不重新解释。",new JSONArray().put(sfid),"upgrade-source-0001");JSONObject r=new JSONObject().put("id","upgrade-memory-0001").put("created",m.getLong("created")).put("sourceId",m.getString("id")).put("files",new JSONArray()).put("files",new JSONArray().put(sfid)).put("title","升级前手工更正").put("content","我在旧版手工改过的内容，需要完整保留。").put("tags",new JSONArray().put("旧版记忆")).put("status","active").put("type","note").put("longTerm",true);db.put("memories",r);new Settings(c).save(new JSONObject().put("baseUrl","https://example.org/v1").put("model","migration-fixture").put("apiKey","migration-fixture-key"));try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"legacy-backup.zip"))){new Backup(c).exportTo(out);}results.putString("status","seeded_1.0");finish(Activity.RESULT_OK,results);return;}
    LedgerSmoke.run(db,c,mode);VolumeSmoke.run(db);String fid=UUID.randomUUID().toString();File image=db.filePath(fid);try(InputStream in=getContext().getAssets().open("reference.png");OutputStream out=new FileOutputStream(image)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
    JSONObject file=new JSONObject().put("id",fid).put("created",System.currentTimeMillis()).put("name","reference.png").put("mime","image/png").put("size",image.length()).put("sha256",MediaProcessor.hash(image)).put("text","").put("processingNote","本机测试图片");db.put("files",file);
    JSONObject message=db.message("user","Data backup reference",new JSONArray().put(fid),UUID.randomUUID().toString());long old=System.currentTimeMillis()-8L*86400000L;String completedId=UUID.randomUUID().toString(),importantId=UUID.randomUUID().toString(),unreadId=UUID.randomUUID().toString(),pendingId=UUID.randomUUID().toString();
    for(String id:new String[]{completedId,importantId,unreadId,pendingId}){JSONObject r=new JSONObject().put("id",id).put("created",old).put("sourceId",message.getString("id")).put("files",new JSONArray().put(fid)).put("title",id.equals(completedId)?"学完的测试资料":id.equals(importantId)?"长期偏好":id.equals(unreadId)?"尚未阅读的资料":"尚未识别的原件").put("content","这是一条数据检查记录。").put("tags",new JSONArray().put("测试资料")).put("type","learning").put("status",id.equals(unreadId)?"active":"completed").put("completedAt",old).put("longTerm",id.equals(importantId)).put("processing",id.equals(pendingId)?"pending":"ready");db.put("memories",r);}
    int count=db.all("memories").length();byte[] exported=backup(db);String json="";try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(exported))){ZipEntry e;while((e=zip.getNextEntry())!=null)if(e.getName().equals("backup.json")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[8192];int n;while((n=zip.read(x))!=-1)b.write(x,0,n);json=b.toString("UTF-8");}}
    check(!json.contains("test-native-key"),"Backup must not include plaintext API keys");new JSONObject(json);JSONObject imported=new Backup(c).importFrom(new ByteArrayInputStream(exported));check(imported.optInt("added")==0,"Duplicate backup must not duplicate records");check(db.all("memories").length()==count,"Record count must be stable");
    boolean refused=false;try{new Backup(c).importFrom(new ByteArrayInputStream(altered(exported,true,false)));}catch(Exception expected){refused=true;}check(refused,"Unsafe paths must be rejected");check(db.all("memories").length()==count,"Rejected import must not alter records");
    refused=false;try{new Backup(c).importFrom(new ByteArrayInputStream(altered(exported,false,true)));}catch(Exception expected){refused=true;}check(refused,"Changed attachment bytes must be rejected");check(MediaProcessor.hash(image).equals(file.getString("sha256")),"Original file must survive rejected import");
    db.delete("memories",completedId);JSONObject restored=new Backup(c).importFrom(new ByteArrayInputStream(exported));check(restored.optInt("added")==1,"Missing record must be restored");check(db.one("memories",completedId)!=null,"Restored record must exist");
    db.archive(true);check(db.one("memories",completedId).getString("status").equals("archived"),"Finished old learning must be archived");check(db.one("memories",importantId).getString("status").equals("completed"),"Long-term memory must remain");check(db.one("memories",unreadId).getString("status").equals("active"),"Unread learning must remain");check(db.one("memories",pendingId).getString("status").equals("completed"),"Unprocessed original must remain");
    JSONObject reminder=new JSONObject().put("id",UUID.randomUUID().toString()).put("created",System.currentTimeMillis()).put("sourceId",message.getString("id")).put("files",new JSONArray()).put("title","提醒触发测试").put("content","这是一条本机提醒测试。").put("tags",new JSONArray().put("测试事项")).put("type","task").put("status","active").put("remindAt",System.currentTimeMillis()+1800);db.put("memories",reminder);Scheduler.set(c,reminder);long deadline=System.currentTimeMillis()+12000;boolean fired=false;while(System.currentTimeMillis()<deadline){Thread.sleep(200);if(db.one("memories",reminder.getString("id")).optBoolean("reminderFired")){fired=true;break;}}check(fired,"Android alarm must trigger the native notification receiver");
    results.putString("status","passed");results.putString("verified","memory ledger: immutable time anchors; time zones; external source dates; conservative pronouns; same-name identities; duplicate evidence; conflicts and resolutions; corrections and changes; historical/as-of/current queries; occurred vs planned events; version restoration; archive protection; indexed pagination; v1 migration and backup import; v2 backup and histories; actual Android alarm; path/SHA rejection");results.putString("fixtureFileId",fid);results.putInt("records",db.all("memories").length());finish(Activity.RESULT_OK,results);
  }catch(Throwable error){results.putString("status","failed");results.putString("error",error.toString());finish(Activity.RESULT_CANCELED,results);}}
}
